import unittest
from decimal import Decimal

from kitty.money import (
    KittyError,
    allocate,
    convert,
    format_cents,
    parse_amount,
    parse_currency,
    parse_date,
    parse_rate,
)


class ParseAmount(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(parse_amount("12"), 1200)
        self.assertEqual(parse_amount("12.5"), 1250)
        self.assertEqual(parse_amount("12.50"), 1250)
        self.assertEqual(parse_amount("0.01"), 1)

    def test_invalid(self):
        for bad in ["0", "0.00", "-3", "1.234", "abc", "", "1e3", "+5", ".5",
                    "NaN", "Infinity", "1,5", " 5"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_amount(bad)


class ParseRate(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(parse_rate("0.92"), Decimal("0.92"))
        self.assertEqual(parse_rate("1.234567"), Decimal("1.234567"))

    def test_invalid(self):
        for bad in ["0", "-1", "abc", "1e2", ".5", "NaN"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_rate(bad)


class ParseCurrencyAndDate(unittest.TestCase):
    def test_currency(self):
        self.assertEqual(parse_currency("usd"), "USD")
        for bad in ["US", "USDX", "U5D", ""]:
            with self.assertRaises(KittyError, msg=bad):
                parse_currency(bad)

    def test_date(self):
        self.assertEqual(parse_date("2026-07-14"), "2026-07-14")
        for bad in ["2026-02-30", "2026-7-14", "14/07/2026", "yesterday"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_date(bad)


class Format(unittest.TestCase):
    def test_format(self):
        self.assertEqual(format_cents(2070), "20.70")
        self.assertEqual(format_cents(-2070), "-20.70")
        self.assertEqual(format_cents(-5), "-0.05")
        self.assertEqual(format_cents(0), "0.00")
        self.assertEqual(format_cents(100000), "1000.00")


class Convert(unittest.TestCase):
    def test_convert(self):
        self.assertEqual(convert(4500, Decimal("0.92")), 4140)
        self.assertEqual(convert(1, Decimal("0.5")), 1)
        self.assertEqual(convert(3, Decimal("0.5")), 2)
        self.assertEqual(convert(1000, Decimal("1")), 1000)


class Allocate(unittest.TestCase):
    def test_equal_three(self):
        self.assertEqual(allocate(1000, [1, 1, 1]), [334, 333, 333])

    def test_shares(self):
        self.assertEqual(allocate(100, [2, 1]), [67, 33])

    def test_percent_hundredths(self):
        self.assertEqual(allocate(1001, [6000, 4000]), [601, 400])

    def test_zero_shares(self):
        self.assertEqual(allocate(1, [1, 1, 1]), [1, 0, 0])

    def test_sums(self):
        self.assertEqual(sum(allocate(920, [333, 667])), 920)
        self.assertEqual(allocate(920, [333, 667]), [307, 613])


if __name__ == "__main__":
    unittest.main()

